<section class="page-section"><div class="container"><div class="row"><aside class="col-lg-4 mb-4"><div class="profile-card"><div class="avatar"><?php if($user['avatar_url']): ?><img src="<?= e(image_url($user['avatar_url'])) ?>" alt="Ảnh đại diện"><?php else: ?><?= e(mb_strtoupper(mb_substr($user['full_name'],0,2))) ?><?php endif; ?></div><h2><?= e($user['full_name']) ?></h2><p class="text-muted">Thành viên từ <?= date('m/Y',strtotime($user['created_at'])) ?></p><nav><a href="#personal">Thông tin cá nhân</a><a href="<?= e(url('/bookings')) ?>">Chuyến của tôi</a><a href="<?= e(url('/wishlist')) ?>">Danh sách yêu thích</a></nav><?php if(!in_array('host',$user['roles'],true)): ?><form method="post" action="<?= e(url('/profile/become-host')) ?>"><?= csrf_field() ?><button class="btn btn-primary btn-block" type="submit">Trở thành Host →</button></form><?php else: ?><a class="btn btn-primary btn-block" href="<?= e(url('/host')) ?>">Mở không gian Host →</a><?php endif; ?></div></aside><div class="col-lg-8"><section class="surface-card" id="personal"><div class="section-title"><div><h1>Thông tin cá nhân</h1><p>Cập nhật thông tin để chủ nhà và khách biết về bạn.</p></div></div><form method="post" enctype="multipart/form-data" action="<?= e(url('/profile')) ?>"><?= csrf_field() ?><div class="form-group"><label for="full_name">Họ và tên</label><input class="form-control" id="full_name" name="full_name" value="<?= e($user['full_name']) ?>" required></div><div class="form-row"><div class="form-group col-md-6"><label>Email</label><input class="form-control" value="<?= e($user['email']) ?>" disabled></div><div class="form-group col-md-6"><label for="phone">Số điện thoại</label><input class="form-control" id="phone" name="phone" value="<?= e($user['phone']) ?>"></div></div><div class="form-group"><label for="avatar">Ảnh đại diện (JPG, PNG, WebP; tối đa 5 MB)</label><input class="form-control-file" id="avatar" name="avatar" type="file" accept="image/jpeg,image/png,image/webp"></div><button class="btn btn-primary" type="submit">Lưu thay đổi</button></form></section><?php if($upcoming): ?><section class="surface-card mt-4"><h2>Chuyến đi sắp tới</h2><?php foreach(array_slice($upcoming,0,2) as $booking): ?><div class="trip-row"><img src="<?= e(image_url($booking['image_url'])) ?>" alt=""><div><strong><?= e($booking['title']) ?></strong><p><?= e($booking['check_in']) ?> → <?= e($booking['check_out']) ?></p></div><span class="status status-<?= e($booking['status']) ?>"><?= e($booking['status']) ?></span></div><?php endforeach; ?></section><?php endif; ?></div></div></div></section>

